import{_ as a,c as t,o as r,af as s}from"./chunks/framework.4G89wRmb.js";const c=JSON.parse('{"title":"全面领导制","description":"","frontmatter":{},"headers":[],"relativePath":"databank/settings/main/comprehensive_leadership.md","filePath":"databank/settings/main/comprehensive_leadership.md"}'),n={name:"databank/settings/main/comprehensive_leadership.md"};function i(o,e,_,p,m,h){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="全面领导制" tabindex="-1">全面领导制 <a class="header-anchor" href="#全面领导制" aria-label="Permalink to “全面领导制”">​</a></h1><p><strong>全面领导制</strong>是<a href="./rengoist_republic_of_nambu.html">联合主义南武共和国</a>的根本政治与经济管理模式，是<a href="./nambu_rengoist_party.html">南武联合党</a>实现其绝对领导的根本制度保障。</p><p>该制度的核心是<strong>集体领导</strong>原则。最高权力由<a href="./supreme_peoples_committee.html">南武最高人民委员会</a>这一集体领导机构统一行使，而非集中于任何个人。所有重大决策均需通过委员会内部讨论形成决议，以此从制度上杜绝个人独裁与个人崇拜的风险，确保权力始终服务于党和人民的集体意志。</p><p>全面领导制由国父<a href="./../people/nambu_kojun.html">南武香淳</a>在其<a href="./rengoism.html">香淳思想</a>中首次构想，并由<a href="./../people/tokishi_kisetsu.html">户岸希节</a>在推行<a href="./kisetsu_line.html">希节路线</a>的经济改革中全面确立。</p>',4)])])}const d=a(n,[["render",i]]);export{c as __pageData,d as default};
